mapper.select:
SELECT id, title, business_type, method, request_method, oper_name, oper_url, oper_ip, oper_param, json_result, status, error_msg, cost_time, oper_time FROM sys_oper_log
AND oper_name LIKE CONCAT('%', #{query.operName}, '%')
AND oper_url LIKE CONCAT('%', #{query.operUrl}, '%')
AND title = #{query.title}
AND business_type = #{query.businessType}
AND status = #{query.status}
ORDER BY oper_time DESC, id DESC
